 void LinkWorksExcel(){Guard();Commit();if(worksExcel!=null){MessageBox.Show(this,"Disconnect the current workbook before choosing another.");return;}using(var d=new SaveFileDialog{Filter="Excel workbook|*.xlsx|Excel macro-enabled workbook|*.xlsm",FileName="Program-of-Works.xlsx",OverwritePrompt=false})if(d.ShowDialog(this)==DialogResult.OK){var next=new ExcelLiveLink(d.FileName,true,false);try{worksExcel=next;lastExcelXml="";SyncWorksExcel();}catch{if(worksExcel==next){worksExcel=null;lastExcelXml="";}next.Dispose();throw;}}}
 void SyncWorksExcel(){if(worksExcel==null)return;syncingExcel=true;try{var project=ProjectInfoStore.Read();string xml=WorksProjectXml()+"|BOQHEADER|"+string.Join("|",new[]{project.Name,project.Location,project.Office,project.OfficeAddress});if(xml==lastExcelXml)return;var issues=WorksValidationIssues();if(issues.Count>0)throw new Exception("Final quantities cannot be exported yet. Save Program of Works to retain your inputs.\n\n"+string.Join("\n",issues.Take(8))+(issues.Count>8?"\nMore issues: select Review inputs.":""));var tables=FinalQuantityTables();worksExcel.UpdateWorksQuantities(tables,BillOfQuantities(),project);lastExcelXml=xml;excelStatus.Text="Excel connected: "+worksExcel.PathName+"\nFinal quantities updated "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+" | Save project data with Save Program of Works.";}finally{syncingExcel=false;}}
