 internal List<WorksExcelTable> WorksExcelTables(){var tables=new List<WorksExcelTable>();var rebar=new List<object[]>();var beamRows=beam.WorksExcelRows(projectRebarPlan);var slabRows=slab.WorksExcelRows(projectRebarPlan);foreach(var pair in new[]{new KeyValuePair<string,object[,]>("Beam",beamRows),new KeyValuePair<string,object[,]>("Slab",slabRows)})for(int r=0;r<pair.Value.GetLength(0);r++){var row=new object[13];row[0]=pair.Key;for(int c=0;c<12;c++)row[c+1]=pair.Value[r,c];rebar.Add(row);}tables.Add(new WorksExcelTable("POW Rebar",new[]{"Category","Description","Mark","Source","Grade","Diameter mm","Main cut kg","Ties cut kg","SFR cut kg","Lap + offcut kg","Total to buy kg","Beam length m","Quantity"},rebar));var bm=beam.ConcreteExcelRows();var sm=slab.WorksMeasureRows();foreach(var pair in new[]{new KeyValuePair<string,object[,]>("POW Beam Measures",bm),new KeyValuePair<string,object[,]>("POW Slab Measures",sm)}){var rows=new List<object[]>();for(int r=0;r<pair.Value.GetLength(0);r++){var row=new object[8];for(int c=0;c<8;c++)row[c]=pair.Value[r,c];rows.Add(row);}tables.Add(new WorksExcelTable(pair.Key,new[]{"Description","Mark","Support","Quantity","Concrete m3","Side / edge forms m2","Soffit m2","Total forms m2"},rows));}
 var openingRows=new List<object[]>();foreach(var o in openings)openingRows.Add(new object[]{o.Id,o.Description,o.Wall,o.Material,o.Kind,o.Width,o.Height,o.Quantity,o.Area,o.LeafPaint,o.JambPaint,o.LeafPaint+o.JambPaint,o.Locks,o.Hinges});tables.Add(new WorksExcelTable("POW Openings",new[]{"Opening ID","Description","Wall ID","Material","Type","Width m","Height m","Quantity","Opening m2","Leaf paint m2","Jamb paint m2","Total wood paint m2","Locksets pcs","Hinges pcs"},openingRows));var wallRows=new List<object[]>();foreach(var w in RegularWalls){PlasterTakeoff p,paint;plasterResults.TryGetValue(w.Id,out p);paintResults.TryGetValue(w.Id,out paint);wallRows.Add(new object[]{w.Id,w.Description,w.Length,w.Height,w.Quantity,w.Gross,w.Deduction(wallOpenings),w.Net(wallOpenings),w.Blocks(wallOpenings),w.Plaster,p==null?0:p.Gross,p==null?0:p.TileDeduction,p==null?0:p.Net,w.Paint,paint==null?0:paint.Net,w.ThicknessMm});}tables.Add(new WorksExcelTable("POW CHB",new[]{"Wall ID","Description","Length m","Height m","Quantity","Gross wall m2","Openings m2","Net CHB m2","CHB pcs","Plaster sides","Plaster base m2","Tiles deducted m2","Net plaster m2","Paint sides","Masonry paint m2","CHB thickness mm"},wallRows));var sizes=new List<object[]>();foreach(int thickness in new[]{100,150})sizes.Add(new object[]{thickness,RegularWalls.Where(w=>w.ThicknessMm==thickness).Sum(w=>w.Net(wallOpenings))});tables.Add(new WorksExcelTable("POW CHB by Thickness",new[]{"CHB thickness mm","Net area m2"},sizes));var scheduleRows=new List<object[]>();foreach(DataGridViewRow row in finishSchedule.Rows)if(!row.IsNewRow&&!Empty(row))scheduleRows.Add(new object[]{Cell(row,0),Cell(row,1),Cell(row,2)});tables.Add(new WorksExcelTable("POW Finish Schedule",new[]{"Finish ID","Description","Group"},scheduleRows));var finishRows=new List<object[]>();foreach(var f in finishItems)finishRows.Add(new object[]{f.Id,f.Description,f.Category,f.Code,f.Wall,f.Kind,f.Side,f.Basis,f.MaterialName??"",f.Total(FindWall(f.Wall),wallOpenings,finishItems)});tables.Add(new WorksExcelTable("POW Finishes",new[]{"Entry ID","Description","Category","Finish code","Wall ID","Type","Side","Area basis","Material / Finish Type","Net finish m2"},finishRows));foreach(var canopyCut in canopyPlan)rebar.Add(new object[]{"Canopy / Ledge",canopyCut.Entry.Description,canopyCut.Entry.Beam,"Manual canopy / ledge",canopyCut.Demand.Grade,canopyCut.Demand.Diameter,canopyCut.Net,0,0,canopyCut.Splice+canopyCut.Waste,canopyCut.Purchase,0,int.Parse(canopyCut.Entry.Quantity)});foreach(var f in footingPlan){rebar.Add(new object[]{"Footing",f.Entry.Description,f.Entry.Beam,"Manual footing",f.Demand.Grade,f.Demand.Diameter,f.Net,0,0,f.Splice+f.Waste,f.Purchase,0,int.Parse(f.Entry.Quantity)});}MasonryExcel(tables);StructuralSteelExcel(tables);var values=new Dictionary<string,double>();foreach(int grade in new[]{40,60})values["Grade"+grade]=rebar.Where(r=>Convert.ToInt32(r[4])==grade).Sum(r=>Convert.ToDouble(r[10]));Func<object[,],int,double> sum=(data,col)=>Enumerable.Range(0,data.GetLength(0)).Sum(r=>Convert.ToDouble(data[r,col]));values["BeamConcrete"]=sum(bm,4);values["SlabConcrete"]=sum(sm,4);values["FootingConcrete"]=footingResults.Sum(x=>x.Concrete);values["ConcreteTotal"]=values["BeamConcrete"]+values["SlabConcrete"]+values["FootingConcrete"]+canopyResults.Sum(q=>q.Concrete);values["BeamForms"]=sum(bm,7);values["SlabForms"]=sum(sm,7);values["FootingForms"]=footingResults.Sum(x=>x.Forms);values["FormsTotal"]=values["BeamForms"]+values["SlabForms"]+values["FootingForms"]+canopyResults.Sum(q=>q.Forms);values["CHBArea"]=RegularWalls.Sum(w=>w.Net(wallOpenings));values["CHBCount"]=wallItems.Sum(w=>w.Blocks(wallOpenings));values["CHB100Area"]=RegularWalls.Where(w=>w.ThicknessMm==100).Sum(w=>w.Net(wallOpenings));values["CHB150Area"]=RegularWalls.Where(w=>w.ThicknessMm==150).Sum(w=>w.Net(wallOpenings));values["Plaster"]=plasterResults.Values.Sum(p=>p.Net);values["MasonryPaint"]=paintResults.Values.Sum(p=>p.Net);values["Wood