ll),wallOpenings,finishItems))));tables.Add(WorksSummaryLayout.CellMap(finishTypeCells));tables.RemoveAll(t=>t.Name=="POW Rebar");tables.Add(new WorksExcelTable("POW Rebar",new[]{"Category","Description","Mark","Source","Grade","Diameter mm","Main cut kg","Ties cut kg","SFR cut kg","Lap + offcut kg","Total to buy kg","Length m","Qty"},rebar));RoofingExcel(tables);EarthworksExcel(tables);return tables;}
 void Guard(){if(!AccessCodes.CanUseApp(2))throw new Exception("Renew Program of Works / estimator access.");}
 void Embed(string title,Form form){HideEmbeddedExcelControls(form);foreach(var footer in form.Controls.OfType<Label>().Where(label=>label.Dock==DockStyle.Bottom))footer.Visible=false;var embeddedBeam=form as EstimatorForm;if(embeddedBeam!=null)embeddedBeam.HideWorksExcelStatus();var page=new TabPage(title);form.TopLevel=false;form.FormBorderStyle=FormBorderStyle.None;form.MinimumSize=Size.Empty;form.Dock=DockStyle.Fill;page.Controls.Add(form);tabs.TabPages.Add(page);form.Show();}
 static void HideEmbeddedExcelControls(Control owner){foreach(Control c in owner.Controls){var button=c as Button;if(button!=null&&button.Text.IndexOf("Excel",StringComparison.OrdinalIgnoreCase)>=0)c.Visible=false;else HideEmbeddedExcelControls(c);}}
