+gross.ToString("0.00")+" m2     -     Openings: "+deduction.ToString("0.00")+" m2     =     Net CHB: "+(gross-deduction).ToString("0.00")+" m2";areaSummary.ForeColor=deduction>gross?Color.Firebrick:PowTheme.Teal;};grid.CellValueChanged+=(sender,args)=>{if(args.RowIndex>=0&&args.ColumnIndex<6&&!updating)updateAreas();};updateAreas();var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=56,Padding=new Padding(8),FlowDirection=FlowDirection.RightToLeft};var apply=new Button{Text="Apply deductions",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};buttons.Controls.Add(apply);buttons.Controls.Add(cancel);dialog.Controls.Add(grid);dialog.Controls.Add(areaSummary);dialog.Controls.Add(buttons);dialog.Controls.Add(note);PowTheme.Apply(dialog);foreach(DataGridViewRow openingRow in grid.Rows)openingRow.MinimumHeight=48;dialog.AcceptButton=apply;dialog.CancelButton=cancel;apply.Click+=(s,e)=>{try{grid.EndEdit();var links=new List<OpeningLink>();var manual=new List<OpeningItem>();foreach(DataGridViewRow r in grid.Rows){string id=Cell(r,0);if(id=="(none)")continue;if(id=="Manual")manual.Add(new OpeningItem{Id=Cell(r,5),Description=Cell(r,1),Wall=wallId,Material="Manual",Kind="Door",Width=Number(r,2),Height=Number(r,3),Quantity=Count(r,4)});else links.Add(new OpeningLink{Wall=wallId,Schedule=id,Quantity=Count(r,4)});}ApplyWallOpeningSelection(wallId,links,manual);dialog.DialogResult=DialogResult.OK;dialog.Close();}catch(Exception x){MessageBox.Show(dialog,x.Message,"Check deductions");}};dialog.ShowDialog(this);}}
 DataGridView FinishGrid(bool wall){var g=Grid(wall?new[]{"Entry ID","Description","Finish / tile code","Wall ID","Type","Side","Area basis","Length m","Height m","Qty (group total)","Opening overlap m2/face","Net per face m2","Finish total m2","Status"}:new[]{"Entry ID","Description","Finish code","Length m","Width m","Qty","Deduction m2 (total)","Gross m2","Net finish m2","Status"},wall?11:7);
