  Action<DataGridViewRow> defaults=r=>{if(wall){r.Cells[4].Value="Tiles";r.Cells[5].Value="A";r.Cells[6].Value="Dimensions";r.Cells[9].Value="1";r.Cells[10].Value="0";}else{r.Cells[5].Value="1";r.Cells[6].Value="0";}};g.DefaultValuesNeeded+=(s,e)=>defaults(e.Row);g.RowsAdded+=(s,e)=>{if(!filling)for(int n=e.RowIndex;n<e.RowIndex+e.RowCount;n++)if(!g.Rows[n].IsNewRow&&g.Rows[n].Cells[wall?9:5].Value==null)defaults(g.Rows[n]);};int material=g.Columns.Add("MaterialName","Group (from Finish ID)");g.Columns[material].ReadOnly=true;g.Columns[material].Width=300;g.Columns[material].DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.Columns[material].DisplayIndex=3;g.Columns[material].DefaultCellStyle.BackColor=Color.FromArgb(235,237,240);g.Columns[material].ToolTipText="Read-only: change the group in Finish Schedule. Presets: Glazed Tiles, Unglazed Tiles, Granite Stone Countertop, Vinyl Floor, etc. Matching names combine across entries/tabs; spacing and letter case are ignored. Blank remains unclassified.";g.CellValueChanged+=(sender,args)=>{if(!wall||filling||args.RowIndex<0||args.ColumnIndex!=material)return;var r=g.Rows[args.RowIndex];string kind=FinishTypeCatalog.KindFor(Cell(r,material));if(kind!=null){filling=true;try{r.Cells[4].Value=kind;}finally{filling=false;}Recalculate();}};g.EditingControlShowing+=(sender,args)=>{var box=args.Control as TextBox;if(box==null)return;if(g.CurrentCell!=null&&g.CurrentCell.ColumnIndex==material){var suggestions=new AutoCompleteStringCollection();suggestions.AddRange(FinishTypeCatalog.Names);box.AutoCompleteCustomSource=suggestions;box.AutoCompleteSource=AutoCompleteSource.CustomSource;box.AutoCompleteMode=AutoCompleteMode.SuggestAppend;}else{box.AutoCompleteMode=AutoCompleteMode.None;box.AutoCompleteSource=AutoCompleteSource.None;}};return g;
