 static void AddCombo(DataGridView g,int index,string name,string[] values){var c=new DataGridViewComboBoxColumn{Name=name,HeaderText=name,Width=140};c.Items.AddRange(values.Cast<object>().ToArray());g.Columns.RemoveAt(index);g.Columns.Insert(index,c);c.DefaultCellStyle.BackColor=Color.FromArgb(255,249,222);}
 WallItem FindWall(string id){return wallItems.FirstOrDefault(w=>string.Equals(w.Id.Trim(),(id??"").Trim(),StringComparison.OrdinalIgnoreCase));}
 void RecalculateFinishes(){RefreshWallIds();ReadFinishSchedule();RefreshFinishIDs();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var pair in new[]{new KeyValuePair<string,DataGridView>("Wall",wallFinishes),new KeyValuePair<string,DataGridView>("Ceiling",ceilingFinishes),new KeyValuePair<string,DataGridView>("Floor",floorFinishes)})foreach(DataGridViewRow r in pair.Value.Rows){if(r.IsNewRow)continue;bool isWall=pair.Key=="Wall";int resultStart=isWall?11:7,last=isWall?13:9;r.Tag=null;for(int n=resultStart;n<=last;n++)r.Cells[n].Value="";if(isWall){bool auto=Cell(r,6)=="Whole wall (auto)";for(int n=7;n<=10;n++){r.Cells[n].ReadOnly=auto;r.Cells[n].Style.BackColor=auto?Color.FromArgb(235,237,240):Color.FromArgb(255,249,222);}}if(Empty(r))continue;try{var f=new FinishItem{Id=Cell(r,0),Description=Cell(r,1),Code=Cell(r,2),Category=pair.Key,Wall=isWall?Cell(r,3):"",Kind=isWall?Cell(r,4):"Other",MaterialName=finishGroups.ContainsKey(Cell(r,2))?finishGroups[Cell(r,2)]:"",Side=isWall?Cell(r,5):"A",Basis=isWall?Cell(r,6):"Dimensions"};bool automatic=isWall&&f.Basis=="Whole wall (auto)";if(!automatic){f.Length=Number(r,isWall?7:3);f.Width=Number(r,isWall?8:4);f.Quantity=Count(r,isWall?9:5);f.Deduction=Number(r,isWall?10:6);}if(!finishGroups.ContainsKey(f.Code))throw new Exception("Assign this entry a Finish ID in Finishing Works > Start.");r.Cells[isWall?14:10].Value=f.MaterialName;if(isWall){string kind=FinishTypeCatalog.KindFor(f.MaterialName);if(kind!=null){f.Kind=kind;r.Cells[4].Value=kind;}}f.Validate();if(!ids.Add(f.Id))throw new Exception("Duplicate finish Entry ID across finish tabs.");WallItem w=isWall?FindWall(f.Wall):null;if(isWall&&w==null)throw new Exception("Wall ID not found or wall has an error.");double net=f.PerFace(w,wallOpenings);if(isWall&&net>w.Net(wallOpenings)+.0000001)throw new Exception("Finish area exceeds the linked net wall area per face.");finishItems.Add(f);r.Tag=f;r.Cells[resultStart].Value=(isWall?net:f.GrossPerFace(null,wallOpenings)).ToString("0.00");r.Cells[resultStart+1].Value=f.Total(w,wallOpenings).ToString("0.00");r.Cells[last].Value=string.IsNullOrWhiteSpace(f.MaterialName)?"Type group in Finish Schedule":"Ready";}catch(Exception x){r.Tag=null;r.Cells[last].Value=x.Message;errors.Add(pair.Key+" finish "+Cell(r,0)+": "+x.Message);}}
  finishTypeCells.Include(finishItems.Select(f=>f.MaterialName));foreach(var grid in new[]{wallFinishes,ceilingFinishes,floorFinishes})foreach(DataGridViewRow row in grid.Rows){var f=row.Tag as FinishItem;if(f==null)continue;int start=grid==wallFinishes?11:7;var wall=FindWall(f.Wall);row.Cells[start+1].Value=f.Total(wall,wallOpenings,finishItems).ToString("0.00");if(f.AutoSurface)row.Cells[start].Value="By face";}
  foreach(DataGridViewRow row in MasonryGrids().SelectMany(g=>g.Rows.Cast<DataGridViewRow>())){if(row.IsNewRow)continue;for(int n=13;n<=15;n++)row.Cells[n].Value="";row.Cells[17].Value="";var w=FindWall(Cell(row,0));if(w==null)continue;try{var p=PlasterTakeoff.Calculate(w,wallOpenings,finishItems);plasterResults[w.Id]=p;row.Cells[13].Value=p.Gross.ToString("0.00");row.Cells[14].Value=p.TileDeduction.ToString("0.00");row.Cells[15].Value=p.Net.ToString("0.00");var paint=PlasterTakeoff.Calculate(w,wallOpenings,finishItems,w.Paint=="Same as plaster"?w.Plaster:w.Paint);paintResults[w.Id]=paint;row.Cells[17].Value=paint.Net.ToString("0.00");if(errors.Count>0)row.Cells[11].Value="Review finish/opening issues before using totals";}catch(Exception x){row.Cells[11].Value=x.Message;errors.Add("Wall "+w.Id+": "+x.Message);}}
 }
 void AppendFinishReport(StringBuilder b){b.AppendLine();b.AppendLine("FINISH MATERIAL / TYPE TOTALS");foreach(var total in FinishTypeRegistry.Totals(finishItems,f=>f.Total(FindWall(f.Wall),wallOpenings,finishItems)))b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-40}{1,14:0.00} m2",total.Name,total.Area));b.AppendLine();b.AppendLine("FINISH AREA SUMMARY");b.AppendLine(string.Format("{0,-12}{1,-25}{2,16}","CATEGORY","FINISH CODE","NET AREA m2"));foreach(var g in finishItems.GroupBy(f=>new{f.Category,f.Code}))b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-12}{1,-25}{2,16:0.00}",g.Key.Category,g.Key.Code,g.Sum(f=>f.Total(FindWall(f.Wall),wallOpenings,finishItems))));b.AppendLine();b.AppendLine("FINISH AREA BACKUP");foreach(var f in finishItems){var w=FindWall(f.Wall);b.AppendLine(f.Id+" | "+f.Description+" | "+f.Category+" / "+f.Code+(string.IsNullOrWhiteSpace(f.MaterialName)?"":" | "+f.MaterialName)+(f.Category=="Wall"?" | Wall "+f.Wall+" / Side "+f.Side:""));if(f.Category=="Wall"&&f.Basis=="Whole wall (auto)")b.AppendLine("  Basis: linked whole wall (automatic door/window deductions)");else b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Dimensions: {0:0.00} x {1:0.00} m x {2} units",f.Length,f.Width,f.Quantity));if(f.AutoSurface){if(f.OnA)b.AppendLine("  Face A: net wall - tiles = "+f.PaintFace(w,wallOpenings,finishItems,true).ToString("0.00")+" m2");if(f.OnB)b.AppendLine("  Face B: net wall - tiles = "+f.PaintFace(w,wallOpenings,finishItems,false).ToString("0.00")+" m2");b.AppendLine("  TOTAL FINISH: "+f.Total(w,wallOpenings,finishItems).ToString("0.00")+" m2");}else b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Area: ({0:0.00} - {1:0.00}) x {2} face(s) = {3:0.00} m2",f.GrossPerFace(w,wallOpenings),f.DeductPerFace(w,wallOpenings),f.Faces,f.Total(w,wallOpenings,finishItems)));b.AppendLine();}}
 static string Cell(DataGridViewRow r,int n){return Convert.ToString(r.Cells[n].Value).Trim();}
 static double Number(DataGridViewRow r,int n){double x;if(!double.TryParse(Cell(r,n),NumberStyles.Float,CultureInfo.InvariantCulture,out x)||double.IsNaN(x)||double.IsInfinity(x))throw new Exception("Check "+r.DataGridView.Columns[n].HeaderText);return x;}
 static int Count(DataGridViewRow r,int n){double v=Number(r,n);if(v<0||v>100000||v!=Math.Truncate(v))throw new Exception("Enter whole numbers for "+r.DataGridView.Columns[n].HeaderText);return (int)v;}
 static bool Empty(DataGridViewRow r){return string.IsNullOrWhiteSpace(Cell(r,0))&&string.IsNullOrWhiteSpace(Cell(r,1))&&string.IsNullOrWhiteSpace(Cell(r,2));}
 void Commit(){if(finishAssignments!=null)finishAssignments.EndEdit();foreach(var g in Tables().Values)g.EndEdit();}
 public void Recalculate(){if(filling||wood==null||walls==null||finishSchedule==null||wallFinishes==null)return;filling=true;try{if(borrowSwell!=null&&borrowShrink!=null)beam.SetProjectSoilFactors((double)borrowSwell.Value,(double)borrowShrink.Value);openings.Clear();wallOpenings.Clear();wallItems.Clear();finishItems.Clear();plasterResults.Clear();paintResults.Clear();errors.Clear();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var g in new[]{wood,aluminum,manualOpeningsGrid})foreach(DataGridViewRow r in g.Rows){if(r.IsNewRow)continue;for(int n=13;n<20;n++)r.Cells[n].Value="";r.Cells[23].Value="";if(Empty(r))continue;try{if(g==wood)AutomaticWoodDimensions(r);var o=new OpeningItem{Id=Cell(r,0),Description=Cell(r,1),Wall=Cell(r,2),Material=g==wood?"Wood":g==manualOpeningsGrid?"Manual":"Aluminum",Kind=Cell(r,3),Width=Number(r,4),Height=Number(r,5),Quantity=Count(r,6),JambDepth=g==wood?Number(r,7):0,JambThickness=g==wood?Number(r,8):0,LeafThickness=g==wood?.045:0,Faces=g==wood?Count(r,10):0,LocksPerUnit=Cell(r,3)=="Door"||Cell(r,11)==""?0:Count(r,11),HingesPerUnit=Cell(r,3)=="Door"||Cell(r,12)==""?0:Count(r,12),Leaves=Cell(r,20)==""?1:Count(r,20),Operation=Cell(r,21)==""?"Swing":Cell(r,21),MouldingProfile=Cell(r,24),Exterior=g!=manualOpeningsGrid&&Cell(r,22)!=""&&bool.Parse(Cell(r,22))};o.Validate();if(!ids.Add(o.Id))throw new Exception("Duplicate Opening ID (including other opening tab).");openings.Add(o);bool autoHardware=o.Kind=="Door"||o.Operation!="Swing"||o.Material=="Manual";foreach(int c in new[]{11,12}){r.Cells[c].ReadOnly=autoHardware;r.Cells[c].Style.BackColor=autoHardware?Color.FromArgb(235,237,240):Color.FromArgb(255,249,222);}if(autoHardware){r.Cells[11].Value=o.EffectiveLocks;r.Cells[12].Value=o.EffectiveHinges;}if(o.Wood){r.Cells[9].Value="45";r.Cells[9].ReadOnly=true;r.Cells[9].Style.BackColor=Color.FromArgb(235,237,240);}else r.Cells[9].ReadOnly=false;r.Cells[13].Value=o.Area.ToString("0.00");r.Cells[14].Value=o.LeafPaint.ToString("0.00");r.Cells[15].Value=o.JambPaint.ToString("0.00");r.Cells[16].Value=(o.LeafPaint+o.JambPaint).ToString("0.00");r.Cells[17].Value=o.Locks;r.Cells[18].Value=o.Hinges;r.Cells[23].Value=o.MouldingLength;r.Cells[19].Value="Ready";}catch(Exception x){r.Cells[19].Value=x.Message;errors.Add("Opening row "+(r.Index+1)+": "+x.Message);}}
  try{wallOpenings.AddRange(OpeningLinks.Resolve(openings,openingAssignments));}catch(Exception x){errors.Add(x.Message);}
  ids.Clear();foreach(DataGridViewRow r in MasonryGrids().SelectMany(g=>g.Rows.Cast<DataGridViewRow>())){if(r.IsNewRow)continue;for(int n=7;n<12;n++)r.Cells[n].Value="";if(Empty(r))continue;try{if(Cell(r,19)!=""&&(Cell(r,2)!=""||Cell(r,3)!=""))throw new Exception("Use Width x Height OR Gross Area, not both. Clear one input method.");if(Cell(r,19)==""&&(Cell(r,2)==""||Cell(r,3)==""))throw new Exception("Enter both Width and Height, or Gross Area only.");NormalizeMasonryRow(r);var w=new WallItem{Material=WallMaterial(r),Id=Cell(r,0),Description=Cell(r,1),Length=Cell(r,19)==""?Number(r,2):1,Height=Cell(r,19)==""?Number(r,3):1,Quantity=Cell(r,19)==""?Count(r,4):1,BlockWidth=Cell(r,5)==""?.4:Number(r,5),BlockHeight=Cell(r,6)==""?.2:Number(r,6),Plaster=Cell(r,12)==""?"2 sides":Cell(r,12),Paint=Cell(r,16)==""?"Same as plaster":Cell(r,16),ThicknessMm=Cell(r,18)==""?150:Number(r,18),EnteredArea=Cell(r,19)==""?(double?)null:Number(r,19)};w.Validate();if(!ids.Add(w.Id))throw new Exception("Duplicate Wall ID: use one row per wall group.");double net=w.Net(wallOpenings);wallItems.Add(w);r.Cells[7].Value=w.Gross.ToString("0.00");r.Cells[8].Value=w.Deduction(wallOpenings).ToString("0.00");r.Cells[9].Value=net.ToString("0.00");r.Cells[10].Value=w.Blocks(wallOpenings);r.Cells[11].Value=errors.Count>0?"Review invalid openings before using quantities":"Ready";}catch(Exception x){r.Cells[11].Value=x.Message;errors.Add("Wall "+Cell(r,0)+": "+x.Message);}}
  foreach(var o in wallOpenings.Where(o=>!ids.Contains(o.Wall)))errors.Add(o.Id+": Wall ID "+o.Wall+" has no CHB row; not deducted.");RecalculateFinishes();RefreshFinishAssignments();RecalculateRoofing();RecalculateGravel();RecalculateEarthworks();UpdateGravelSummary();RecalculateCanopies();RecalculateStructuralSteel();RecalculateMouldings();RefreshProjectRebarPlan();UpdateCanopyPurchases();UpdateMasonryTotals();status.Text=(errors.Count>0?"REVIEW: "+errors.Count+" issue(s) | ":"")+"Wood paint "+openings.Sum(o=>o.LeafPaint+o.JambPaint).ToString("0.00")+" m2 | Net CHB "+RegularWalls.Sum(w=>w.Net(wallOpenings)).ToString("0.00")+" m2 | CHB 100mm "+RegularWalls.Where(w=>w.ThicknessMm==100).Sum(w=>w.Net(wallOpenings)).ToString("0.00")+" m2 | CHB 150mm "+RegularWalls.Where(w=>w.ThicknessMm==150).Sum(w=>w.Net(wallOpenings)).ToString("0.00")+" m2 | Plaster "+plasterResults.Values.Sum(p=>p.Net).ToString("0.00")+" m2 | Masonry paint "+paintResults.Values.Sum(p=>p.Net).ToString("0.00")+" m2";UpdateReportPreview();UpdateDashboard();homeSummary.Text=status.Text;}finally{filling=false;}ScheduleWorksExcel();}
 string OpeningReport(){var b=new StringBuilder();b.AppendLine("PROGRAM OF WORKS | QUANTITY BACKUP");b.AppendLine("OPENINGS SUMMARY");b.AppendLine(string.Format("{0,-10}{1,15}{2,15}{3,13}{4,13}","MATERIAL","OPENING m2","PAINT m2","LOCKSETS","HINGES"));foreach(string material in new[]{"Wood","Aluminum","Manual"}){var list=openings.Where(o=>o.Material==material);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-10}{1,15:0.00}{2,15:0.00}{3,13}{4,13}",material,list.Sum(o=>o.Area),list.Sum(o=>o.LeafPaint+o.JambPaint),list.Sum(o=>o.Locks),list.Sum(o=>o.Hinges)));}b.AppendLine();AppendMouldingReport(b);b.AppendLine("OPENING DETAILS");foreach(var o in openings){b.AppendLine(o.Id+" | "+o.Description+" | "+o.Material+" "+o.Kind+" | Wall "+o.Wall);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  {0:0.00} x {1:0.00} m x {2} units = {3:0.00} m2 opening",o.Width,o.Height,o.Quantity,o.Area));if(o.Wood){b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Leaf {0:0.00} x {1:0.00} m | {2} face(s)",o.LeafWidth,o.LeafHeight,o.Faces));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Paint: leaf {0:0.00} + jamb {1:0.00} = {2:0.00} m2",o.LeafPaint,o.JambPaint,o.LeafPaint+o.JambPaint));}if(o.Material!="Manual")b.AppendLine("  Locksets "+o.Locks+" pcs | Hinges "+o.Hinges+" pcs");b.AppendLine();}
