 Dictionary<string,DataGridView> Tables(){return WithMasonry(new Dictionary<string,DataGridView>{{"Wood",wood},{"Aluminum",aluminum},{"Walls",walls},{"CHBOpenings",manualOpeningsGrid},{"FinishSchedule",finishSchedule},{"WallFinishes",wallFinishes},{"CeilingFinishes",ceilingFinishes},{"FloorFinishes",floorFinishes},{"InsulationRolls",insulationRolls},{"RoofProfiles",roofProfiles},{"RoofSheets",roofSheets},{"RoofAccessories",roofAccessories},{"CutFill",cutFill},{"Footings",footings},{"Canopies",canopies},{"GravelEntries",gravelEntries},{"MouldingEntries",mouldingEntries}});}
 static int[] InputColumns(string section){if(section=="MouldingEntries")return Enumerable.Range(0,5).ToArray();if(SteelSections.Contains(section))return Enumerable.Range(0,SteelInputCount(section)).ToArray();if(section=="InsulationRolls")return Enumerable.Range(0,3).ToArray();if(section=="RoofProfiles")return Enumerable.Range(0,5).ToArray();if(section=="CutFill")return Enumerable.Range(0,11).ToArray();if(section=="GravelEntries")return Enumerable.Range(0,6).ToArray();if(section=="Canopies")return Enumerable.Range(0,19).ToArray();if(section=="Footings")return Enumerable.Range(0,28).ToArray();if(section=="RoofSheets")return Enumerable.Range(0,12).Concat(new[]{17,18}).ToArray();if(section=="RoofAccessories")return Enumerable.Range(0,8).ToArray();if(section=="FinishSchedule")return new[]{0,1,2};if(IsMasonrySection(section))return new[]{0,1,2,3,4,5,6,12,16,18,19};if(section=="WallFinishes")return Enumerable.Range(0,11).Concat(new[]{14}).ToArray();if(section=="CeilingFinishes"||section=="FloorFinishes")return Enumerable.Range(0,7).Concat(new[]{10}).ToArray();return Enumerable.Range(0,13).Concat(new[]{20,21,22,24}).ToArray();}
 string DataXml(){var d=new XmlDocument();var root=d.CreateElement("ProgramOfWorks");root.SetAttribute("version","15");WriteEarthSettings(root);WriteSteelProfiles(root);d.AppendChild(root);foreach(var pair in Tables()){var section=d.CreateElement(pair.Key);root.AppendChild(section);foreach(DataGridViewRow r in pair.Value.Rows){if(r.IsNewRow||Empty(r))continue;var row=d.CreateElement("Entry");foreach(int c in InputColumns(pair.Key))row.SetAttribute("c"+c,Cell(r,c));section.AppendChild(row);}}finishTypeCells.Write(root);OpeningLinks.Write(root,openingAssignments);return d.OuterXml;}
